module 	UART2(
	input  wire	     ipClk,
	input  wire		 ipReset,
	input  wire[7:0]ipTxData,
	input  wire		 ipTxSend,
	output reg 	     opTxBusy,
	output reg       opTx,
	input  wire      ipRx,
	output reg [7:0]opRxData,
	output reg		 opRxValid
);
reg [3:0]TxBdCount;
reg [3:0]RxBdCount;
reg [1:0]TxState;
reg [1:0]RxState;
reg [7:0]RxData;
always @(posedge ipClk or posedge ipReset) begin
	if(ipReset) begin
		TxBdCount <= 0;
		RxBdCount <= 0;
		TxState <= 0;
		RxState <= 0;
		opTxBusy <= 0;
		opTx <= 0;
		opRxData <= 0;
		opRxValid <= 0;
	end
	else begin
		case(TxState)
			TxIdle: begin
				if(ipTxSend) begin
					TxState <= Sending;
					opTxBusy <= 1;
					opTx <= 0;
					RxState <= RxIdle;
					RxData <= 0;
					RxBdCount <= 0;
				end
			end
			Sending: begin
				if(TxBdCount == 433) begin
					TxState <= TxDone;
					opTxBusy <= 0;
				end
				else begin
					TxBdCount <= TxBdCount + 1;
					opTx <= ipTxData[0];
					RxState <= RxIdle;
					RxData <= 0;
					RxBdCount <= 0;
				end
			end
			TxDone: begin
				TxState <= TxIdle;
				opTxBusy <= 0;
			end
			default: begin
				TxState <= TxIdle;
				opTxBusy <= 0;
			end
		endcase
		case(RxState)
			RxIdle: begin
				if(ipRx == 0) begin
					RxState <= Receiving;
					RxBdCount <= 0;
				end
			end
			Receiving: begin
				if(RxBdCount == 433) begin
					RxState <= RxDone;
					opRxData <= RxData;
					opRxValid <= 1;
				end
				else begin
					RxBdCount <= RxBdCount + 1;
					RxData <= {RxData[6:0],ipRx};
				end
			end
			RxDone: begin
				RxState <= RxIdle;
				opRxValid <= 0;
			end
			default: begin
				RxState <= RxIdle;
				opRxValid <= 0;
			end
		endcase
	end
end
endmodule

