module fifo_simple
#(
    parameter               WIDTH=16,
    parameter               DEPTH=16,
    parameter               PROG_FULL=14
)    
(
    input   wire                    reset_p,    
    input   wire                    clk,        

    input   wire    [WIDTH-1:0]     data_i,
    input   wire                    data_we,

    output  wire    [WIDTH-1:0]     data_o,
    input   wire                    data_rd,

    output  wire                    prog_full,
    output  wire                    full,
    output  wire                    empty,
    output  reg                     overflow,
    output  reg                     underflow

);
reg [WIDTH-1:0] mem [0:DEPTH-1];
reg [DEPTH-1:0] wr_ptr;
reg [DEPTH-1:0] rd_ptr;
reg [DEPTH-1:0] word_count;
reg [DEPTH-1:0] prog_full_count;

assign data_o = mem[rd_ptr];

always @(posedge clk) begin
    if (reset_p) begin
        wr_ptr <= 0;
        rd_ptr <= 0;
        word_count <= 0;
        prog_full_count <= 0;
        overflow <= 0;
        underflow <= 0;
    end else begin
        if (data_we) begin
            if (word_count == DEPTH) begin
                overflow <= 1;
            end
            mem[wr_ptr] <= data_i;
            wr_ptr <= wr_ptr + 1;
            word_count <= word_count + 1;
        end else begin
            if (word_count == 0) begin
                underflow <= 1;
            end
            rd_ptr <= rd_ptr + 1;
            word_count <= word_count - 1;
        end
        if (word_count == PROG_FULL) begin
            prog_full_count <= word_count;
        end
    end
end

assign prog_full = (prog_full_count != 0);
assign full = (word_count != 0);
assign empty = (word_count == 0);
assign overflow = 0;
assign underflow = 0;

endmodule

module submulor_2_stage_unsigned_10_bit(
