module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [1:0]
  reset = 0,
  idle = 1,
  running = 2,
  complete = 3;
reg [1:0] current_state;
reg [1:0] next_state;
  always @(posedge clk, posedge resetn) begin
    if((resetn == 1'b0)) begin
      current_state <= reset;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY, WVALID, WSTRB, data) begin
    next_state <= current_state;
    WVALID <= 1'b0;
    WSTRB <= 4'b0000;
    done <= 1'b0;
    case(current_state)
    reset : begin
      if((go == 1'b1)) begin
        next_state <= idle;
      end
    end
    idle : begin
      if((go == 1'b1)) begin
        next_state <= running;
      end
    end
    running : begin
      if((WREADY == 1'b1)) begin
        if((WVALID == 1'b1)) begin
          next_state <= complete;
        end
        else begin
          next_state <= running;
        end
      end
      else begin
        next_state <= running;
      end
    end
    complete : begin
      if((WREADY == 1'b1)) begin
        done <= 1'b1;
        next_state <= idle;
      end
      else begin
        next_state <= complete;
      end
    end
    endcase
  end
  always @(current_state, data) begin
    WDATA <= data;
    case(current_state)
    running : begin
      WVALID <= 1'b1;
      WSTRB <= 4'b1111;
    end
    complete : begin
      WVALID <= 1'b0;
      WSTRB <= 4'b0000;
    end
    endcase
  end
endmodule

