module receiver(input wire rx,
		output reg rdy,
		input wire rdy_clr,
		input wire clk_50m,rst,
		input wire clken,
		output reg [7:0] data);
parameter START = 0;
	parameter DATA = 1;
	parameter STOP = 2;
	reg [1:0] state;
	reg [3:0] cnt;
	reg [7:0] rx_data;
	reg rx_data_en;
	always @(posedge clk_50m or posedge rst) begin
		if(rst) begin
			state <= START;
			cnt <= 0;
			rx_data_en <= 0;
			rx_data <= 0;
			rdy <= 0;
		end
		else begin
			if(clken) begin
				case(state)
					START: begin
						if(!rx) begin
							state <= DATA;
							cnt <= 0;
							rx_data_en <= 0;
							rx_data <= 0;
							rdy <= 0;
						end
					end
					DATA: begin
						if(cnt == 0) begin
							if(!rx) begin
								state <= STOP;
								cnt <= cnt + 1;
							end
						end
						else if(cnt < 8) begin
							rx_data <= {rx_data[6:0],rx};
							cnt <= cnt + 1;
						end
					end
					STOP: begin
						if(cnt == 0) begin
							if(rx) begin
								state <= START;
								rdy <= 1;
							end
						end
						else if(cnt < 9) begin
							if(rx) begin
								state <= START;
								rdy <= 0;
							end
							else begin
								state <= DATA;
								cnt <= cnt + 1;
							end
						end
					end
				endcase
			end
			else begin
				state <= START;
				cnt <= 0;
				rx_data_en <= 0;
				rx_data <= 0;
				rdy <= 0;
			end
		end
	end
	always @(posedge clk_50m or posedge rst) begin
		if(rst) begin
			rdy_clr <= 0;
		end
		else begin
			rdy_clr <= 1;
		end
	end
endmodule

