  parameter FREQ_MHZ = 2,
  parameter BAUDS    = 115200	       
) (
    input clk,
    input resetq,
    output tx,
    input  rx,
    input  wr,
    input  rd,
    input  [7:0] tx_data,
    output [7:0] rx_data,
    output busy,
    output valid
);
localparam DIV = FREQ_MHZ / BAUDS;
  localparam DIVCYCLES = 1000000 / (DIV * 1000);
  reg [31:0] recv_divcnt;
  reg [7:0] recv_pattern;
  reg [7:0] recv_buf_data;
  reg recv_buf_valid;
  reg recv_busy;
  reg [31:0] send_divcnt;
  reg [2:0] send_state;
  reg send_tx;
  assign rx_data = recv_buf_data;
  assign busy = recv_busy;
  assign valid = recv_buf_valid;
  always @(posedge clk or negedge resetq) begin
    if (!resetq) begin
      recv_divcnt <= 0;
      recv_pattern <= 0;
      recv_buf_data <= 0;
      recv_buf_valid <= 0;
      recv_busy <= 0;
      send_divcnt <= 0;
      send_state <= 0;
      send_tx <= 0;
    end else begin
      if (recv_divcnt == 0) begin
        recv_divcnt <= recv_divcnt + 1;
        if (rx == 1'b0) begin
          recv_divcnt <= 0;
          recv_pattern <= {recv_pattern[6:0], rx};
          recv_buf_valid <= 0;
          recv_busy <= 1;
        end
      end else begin
        recv_divcnt <= recv_divcnt + 1;
        if (recv_divcnt == (DIVCYCLES - 1)) begin
          recv_divcnt <= 0;
          recv_buf_data <= recv_pattern;
          recv_buf_valid <= 1;
          recv_busy <= 0;
        end
      end
    end
  end
  always @(posedge clk or negedge resetq) begin
    if (!resetq) begin
      send_divcnt <= 0;
      send_state <= 0;
      send_tx <= 0;
    end else begin
      if (send_divcnt == 0) begin
        send_divcnt <= send_divcnt + 1;
        if (send_state == 0) begin
          send_state <= 1;
          send_tx <= 1;
        end else if (send_state == 1) begin
          send_state <= 2;
          send_divcnt <= 0;
        end else if (send_state == 2) begin
          send_state <= 3;
          send_divcnt <= 0;
        end else if (send_state == 3) begin
          send_state <= 4;
          send_divcnt <= 0;
        end else if (send_state == 4) begin
          send_state <= 5;
          send_divcnt <= 0;
        end else if (send_state == 5) begin
          send_state <= 6;
          send_divcnt <= 0;
        end else if (send_state == 6) begin
          send_state <= 7;
          send_divcnt <= 0;
        end else if (send_state == 7) begin
          send_state <= 0;
          send_tx <= 0;
        end
      end else begin
        send_divcnt <= send_divcnt + 1;
        if (send_divcnt == (DIVCYCLES - 1)) begin
          send_divcnt <= 0;
          if (send_state == 0) begin
            send_tx <= 1;
          end else if (send_state == 1) begin
            send_tx <= 0;
          end else if (send_state == 2) begin
            send_tx <= tx_data[7];
          end else if (send_state == 3) begin
            send_tx <= tx_data[6];
          end else if (send_state == 4) begin
            send_tx <= tx_data[5];
          end else if (send_state == 5) begin
            send_tx <= tx_data[4];
          end else if (send_state == 6) begin
            send_tx <= tx_data[3];
          end else if (send_state == 7) begin
            send_tx <= tx_data[2];
          end else begin
            send_tx <= tx_data[1];
          end
        end
      end
    end
  end
  assign tx = send_tx;
endmodule

