	input clock, reset;
	input[4:0] Rm, Rs, Rd;
	output[31:0] Rm_data, Rs_data;
	input[31:0] Rd_data;
reg[31:0] regs[31:0];

	assign Rm_data = regs[Rm];
	assign Rs_data = regs[Rs];

	always @(posedge clock or posedge reset) begin
		if (reset) begin
			integer i;
			for (i = 0; i < 32; i = i + 1) begin
				regs[i] = 0;
			end
		end
		else begin
			if (Rd != 0) begin
				regs[Rd] = Rd_data;
			end
		end
	end
endmodule

