module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_SYNC_PULSE=96;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_TOTAL=1600;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_SYNC_PULSE=2;
parameter [31:0] V_BACK_PORCH=33;
parameter [31:0] V_TOTAL=480;
reg [10:0] x = 0;
reg [10:0] y = 0;
reg h_sync = 1'b1;
reg v_sync = 1'b1;
reg disp_en = 1'b0;
  always @(posedge RST, posedge CLK) begin
    if((RST == 1'b1)) begin
      x <= 0;
      y <= 0;
      h_sync <= 1'b1;
      v_sync <= 1'b1;
      disp_en <= 1'b0;
    end else begin
      if((x == (H_TOTAL - 1))) begin
        x <= 0;
        if((y == (V_TOTAL - 1))) begin
          y <= 0;
        end
        else begin
          y <= y + 1;
        end
      end
      else begin
        x <= x + 1;
      end
      if((x < (H_ACTIVE - 1))) begin
        h_sync <= 1'b0;
      end
      else begin
        h_sync <= 1'b1;
      end
      if((y < (V_ACTIVE - 1))) begin
        v_sync <= 1'b0;
      end
      else begin
        v_sync <= 1'b1;
      end
      if((h_sync == 1'b0 && v_sync == 1'b0)) begin
        disp_en <= 1'b1;
      end
      else begin
        disp_en <= 1'b0;
      end
    end
  end
  assign H_SYNC = h_sync;
  assign V_SYNC = v_sync;
  assign X = x;
  assign Y = y;
  assign DISP_EN = disp_en;
endmodule

