module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code_reg;
    reg [3:0] scan_counter;
    reg scan_ready_reg;
    always @(posedge reset or negedge i_clock) begin
        if (reset == 1'b1) begin
            scan_code_reg <= 8'b0;
            scan_counter <= 4'b0;
            scan_ready_reg <= 1'b0;
        end else begin
            if (i_clock == 1'b0) begin
                scan_code_reg[scan_counter] <= i_data;
                scan_counter <= scan_counter + 1;
                if (scan_counter == 4'b1111) begin
                    scan_ready_reg <= 1'b1;
                end
                if (scan_counter == 4'b1110) begin
                    if (i_data == scan_code_reg[0] ^ scan_code_reg[1] ^ scan_code_reg[2] ^ scan_code_reg[3] ^ scan_code_reg[4] ^ scan_code_reg[5] ^ scan_code_reg[6] ^ scan_code_reg[7]) begin
                        scan_ready_reg <= 1'b1;
                    end else begin
                        scan_ready_reg <= 1'b0;
                    end
                end
                if (scan_counter == 4'b1111) begin
                    scan_counter <= 4'b0;
                end
            end
        end
    end
    assign scan_code = scan_code_reg;
    assign scan_ready = scan_ready_reg;
endmodule

