module stallmem (DataOut, Done, Stall, CacheHit, err, Addr, DataIn, Rd, Wr, createdump, clk, rst);

   output  [15:0] DataOut;
   output         Done;
   output         Stall;
   output         CacheHit;
   input [15:0]   DataIn;
   input [15:0]   Addr;
   input          Wr;
   input          Rd;
   input          createdump;
   input          clk;
   input          rst;
   output         err;
reg [15:0] DataOut;
   reg Done;
   reg Stall;
   reg CacheHit;
   reg [7:0] mem [0:63];
   reg loaded;
   reg [16:0] largest;
   reg [31:0] rand_pat;
   wire ready;
   wire muxSel;

   assign ready = Wr | Rd;
   assign muxSel = ready & ~Wr;
   assign Stall = ~ready;
   assign CacheHit = 1'b0;
   assign err = ready & Addr[0];

   initial begin
      loaded = 1'b0;
      largest = 17'b0;
      rand_pat = 32'b0;
      Done = 1'b0;
      Stall = 1'b0;
      CacheHit = 1'b0;
      DataOut = 16'b0;
   end

   always @(posedge clk) begin
      if (rst) begin
         loaded = 1'b0;
         largest = 17'b0;
         rand_pat = 32'b0;
         Done = 1'b0;
         Stall = 1'b0;
         CacheHit = 1'b0;
         DataOut = 16'b0;
      end
      else begin
         if (createdump) begin
            $display("stallmem: %t", $time);
         end
         if (Stall) begin
            #1;
         end
         if (Wr) begin
            mem[Addr] <= DataIn;
         end
         if (Rd) begin
            DataOut = mem[Addr];
         end
         if (err) begin
            DataOut = mem[largest];
