  assign coeff_forward = b_reg;
  assign sample_out = p_reg[ACCUM_WIDTH-1:ACCUM_WIDTH-OUT_WIDTH];
  always @(posedge clk) begin
    if (reset) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
      m_reg <= 0;
      p_reg <= 0;
    end
    else if (clear) begin
      a_reg <= 0;
      b_reg <= 0;
      ad_reg <= 0;
