module mult_a_signed_b_signed
#(
	parameter	A_WIDTH		= 3,
	parameter	B_WIDTH		= 3,
	parameter	Q_WIDTH		= A_WIDTH+B_WIDTH,
	parameter	LATENCY		= 1
)
(
	input	arst,
	input	clk,

	input signed	[A_WIDTH-1:0]	a,
	input signed	[B_WIDTH-1:0]	b,
	output signed	[Q_WIDTH-1:0]	o
);
reg signed	[A_WIDTH-1:0]	r_a_1P;
reg signed	[B_WIDTH-1:0]	r_b_1P;
reg signed	[Q_WIDTH-1:0]	r_q_P[LATENCY-1:0];

assign o	= r_q_P[LATENCY-1];

always @(posedge arst or posedge clk)
begin
	if (arst)
		begin
			r_a_1P	<= 0;
			r_b_1P	<= 0;
		end
	else
		begin
			r_a_1P	<= a;
			r_b_1P	<= b;
		end
end

always @(posedge arst or posedge clk)
begin
	if (arst)
		begin
			r_q_P[0]	<= 0;
		end
	else
		begin
			r_q_P[0]	<= r_a_1P * r_b_1P;
		end
end

genvar i;
generate
	for (i=1; i<LATENCY; i=i+1)
		begin: gen_q_P
			always @(posedge arst or posedge clk)
				begin
					if (arst)
						begin
							r_q_P[i]	<= 0;
						end
					else
						begin
							r_q_P[i]	<= r_q_P[i-1];
						end
				end
		end
endgenerate

endmodule

