    else begin
      rdata0_int <= rdata0[NBITS-1:0] | rdata0[2*NBITS-1:NBITS];
      rdata1_int <= rdata1[NBITS-1:0] | rdata1[2*NBITS-1:NBITS];
      rdata2_int <= rdata2[NBITS-1:0] | rdata2[2*NBITS-1:NBITS];
      rdata3_int <= rdata3[NBITS-1:0] | rdata3[2*NBITS-1:NBITS];
    end
  end
  always @(posedge hclk or negedge hresetn) begin
    if (!hresetn) begin
      rdata0_int <= 0;
      rdata1_int <= 0;
      rdata2_int <= 0;
      rdata3_int <= 0;
    end
    else begin
      rdata0_int <= rdata0[NBITS-1:0] | rdata0[2*NBITS-1:NBITS];
      rdata1_int <= rdata1[NBITS-1:0] | rdata1[2*NBITS-1:NBITS];
      rdata2_int <= rdata2[NBITS-1:0] | rdata2[2*NBITS-1:NBITS];
      rdata3_int <= rdata3[NBITS-1:0] | rdata3[2*NBITS-1:NBITS];
