	input wire clk,rst,
	input [7:0] in3,in2,in1,in0,
	output reg [3:0] anodo,
	output reg [7:0] catodo
    );
localparam N = 18;
	reg [N-1:0] q_reg,q_next;
	
	always @(posedge clk or posedge rst)
	begin
		if(rst)
			q_reg <= 0;
		else
			q_reg <= q_next;
	end
	
	always @(*)
	begin
		q_next = q_reg + 1;
		case(q_reg[N-1:N-2])
			2'b00: begin
				anodo = 4'b0001;
				catodo = in0;
			end
			2'b01: begin
				anodo = 4'b0010;
				catodo = in1;
			end
			2'b10: begin
				anodo = 4'b0100;
				catodo = in2;
			end
			2'b11: begin
				anodo = 4'b1000;
				catodo = in3;
			end
		endcase
	end
endmodule

