module boardSynchroniser(
    input clk,
	 input synch_en,
    input toggle_en,
    input [1:0] cnt_n,
    input [1:0] cnt_m,
    input opMode,
    output reg synchroStatus = 1'b0,
    inout syncInOut
    );
reg [1:0] cnt = 2'b00;
    reg synch = 1'b0;
    reg lastToggle = 1'b0;
    always @(posedge clk) begin
        if (toggle_en == 1'b1 && lastToggle == 1'b0) begin
            if (cnt == cnt_n) begin
                synch = 1'b1;
            end
            else if (cnt == cnt_m) begin
                synch = 1'b0;
            end
            cnt <= cnt + 2'b01;
        end
        lastToggle <= toggle_en;
    end
    always @(posedge clk) begin
        if (opMode == 1'b1) begin
            synchroStatus <= synch;
        end
        else begin
            syncInOut <= synch;
        end
    end
endmodule

