module flag(

	input [2:0]sign,
	input islow,
	input carry_in,


	output reg carry_out,
	output reg led2
);
reg [2:0]regcarry;

always @(*)
begin
	if(islow)
	begin
		carry_out = 0;
		regcarry = carry_in;
	end
	else
	begin
		carry_out = regcarry;
	end
end

always @(*)
begin
	if(islow)
	begin
		if(carry_out)
			led2 = 0;
		else
			led2 = 1;
	end
	else
	begin
		if(sign == 3'b000)
			led2 = 0;
		else if(sign == 3'b001)
			led2 = 1;
		else if(sign == 3'b010)
			led2 = 0;
		else if(sign == 3'b011)
			led2 = 1;
		else if(sign == 3'b100)
			led2 = 0;
		else if(sign == 3'b101)
			led2 = 1;
		else if(sign == 3'b110)
			led2 = 0;
		else if(sign == 3'b111)
			led2 = 1;
	end
end

endmodule

