module diffeq_paj_convert (Xinport, Yinport, Uinport, Aport, DXport, Xoutport, Youtport, Uoutport, CLK, reset);
    input[31:0] Xinport; 
    input[31:0] Yinport; 
    input[31:0] Uinport; 
    input[31:0] Aport; 
    input[31:0] DXport; 
    input CLK; 
    input reset; 
    output[31:0] Xoutport; 
    output[31:0] Youtport; 
    output[31:0] Uoutport;
reg[31:0] x_var; 
    reg[31:0] y_var; 
    reg[31:0] u_var; 
    wire[31:0] temp; 
    assign Xoutport = x_var; 
    assign Youtport = y_var; 
    assign Uoutport = u_var; 
    always @(posedge CLK or posedge reset) begin
        if (reset == 1) begin
            x_var <= 0; 
            y_var <= 0; 
            u_var <= 0; 
        end
        else begin
            x_var <= x_var + DXport; 
            temp <= (x_var - Aport) * (x_var - Aport); 
            y_var <= (yinport + (u_var * (x_var - Aport))) - (temp * (yinport - (u_var * (x_var - Aport)))); 
            u_var <= (y_var - (x_var - Aport) * (y_var - (x_var - Aport))) - (temp * (u_var - (x_var - Aport) * (u_var - (x_var - Aport)))); 
        end
    end
endmodule

