module scan_hex_led_disp(
    input clk,reset,
    input [3:0] hex3,hex2,hex1,hex0,
    input [3:0] dp,
    output reg[3:0] en, 
    output reg[7:0] sseg
    );
reg [3:0] cnt;
    always @(posedge clk or posedge reset)
    begin
        if(reset)
            cnt <= 0;
        else
            cnt <= cnt + 1;
    end
    always @(*)
    begin
        case(cnt)
            0: begin
                en <= 4'b0001;
                sseg <= hex3;
                sseg[6] <= dp[0];
            end
            1: begin
                en <= 4'b0010;
                sseg <= hex2;
                sseg[6] <= dp[1];
            end
            2: begin
                en <= 4'b0100;
                sseg <= hex1;
                sseg[6] <= dp[2];
            end
            3: begin
                en <= 4'b1000;
                sseg <= hex0;
                sseg[6] <= dp[3];
            end
        endcase
    end
endmodule

module linear_layer (
    input [63:0] x0, x1, x2, x3, x4,
    output [63:0] o0, o1, o2, o3, o4
);
assign o0 = x0 ^ x1 ^ x2 ^ x3 ^ x4;
    assign o1 = x0 ^ x1 ^ x2 ^ x3 ^ x4;
    assign o2 = x0 ^ x1 ^ x2 ^ x3 ^ x4;
    assign o3 = x0 ^ x1 ^ x2 ^ x3 ^ x4;
    assign o4 = x0 ^ x1 ^ x2 ^ x3 ^ x4;
endmodule

module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    assign tmp = {{3{data_i[13]}}, data_i};
    always @(*) begin
        case (shift_i)
            0: data_o = tmp;
            1: data_o = tmp << 1;
            2: data_o = tmp << 2;
            3: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @(a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] mem [0:31];
initial begin
    int i;
    for (i = 0; i < 32; i = i + 1) begin
        mem[i] = 0;
    end
end
always @(posedge clk) begin
    if (MemWrite) begin
        mem[addr] = write_data;
    end
end
assign read_data = (MemRead) ? mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
wire [BITS:0] enable_wires;

assign out = cnt;
assign enable_wires[0] = ena;
assign ovf = (cnt == 0) ? 1'b1 : (cnt == (2**BITS - 1)) ? 1'b1 : 1'b0;

genvar i;
generate
    for (i = 0; i < BITS; i = i + 1) begin : gen
        always @(posedge clk or posedge rst) begin
            if (rst) begin
                cnt[i] <= 1'b0;
            end else begin
                if (enable_wires[i]) begin
                    if (updown) begin
                        cnt[i] <= cnt[i] + 1'b1;
                    end else begin
                        cnt[i] <= cnt[i] - 1'b1;
                    end
                end
            end
        end
    end
endgenerate

endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
		integer i;
		always @ (reg1) begin
			for (i = 0; i < 16; i = i + 1) begin
				if (reg1[3:0] > 4) begin
					reg1[3:0] = reg1[3:0] + 3;
				end
				if (reg1[7:4] > 4) begin
					reg1[7:4] = reg1[7:4] + 3;
				end
				if (reg1[11:8] > 4) begin
					reg1[11:8] = reg1[11:8] + 3;
				end
				if (reg1[15:12] > 4) begin
					reg1[15:12] = reg1[15:12] + 3;
				end
				reg1 = reg1 >> 1;
			end
		end
		assign b = reg1[3:0];
		assign s = reg1[7:4];
		assign g = reg1[11:8];
		assign q = reg1[15:12];
	endmodule

