module IB_ENDPOINT_OP_DONE_BUFFER(
input wire CLK,
input wire RESET,
input wire [15:0] RD_COMPL_TAG,
input wire RD_COMPL_START,
input wire RD_COMPL_DONE,
input wire [15:0] BM_TAG,
input wire BM_DONE,
output wire [15:0] OP_TAG,
output wire OP_DONE
); 

reg [15:0] rd_compl_tag;
reg rd_compl_start;
reg rd_compl_done;
reg bm_tag_valid;
reg bm_done;
  always @(posedge CLK, posedge RESET) begin
    if((RESET == 1'b1)) begin
      rd_compl_tag <= {16{1'b0}};
      rd_compl_start <= 1'b0;
      rd_compl_done <= 1'b0;
      bm_tag_valid <= 1'b0;
      bm_done <= 1'b0;
    end else begin
      rd_compl_start <= RD_COMPL_START;
      rd_compl_done <= RD_COMPL_DONE;
      bm_tag_valid <= BM_DONE;
      bm_done <= BM_DONE;
      if((RD_COMPL_START == 1'b1 && RD_COMPL_DONE == 1'b0)) begin
        rd_compl_tag <= RD_COMPL_TAG;
      end
    end
  end
  assign OP_DONE = rd_compl_start == 1'b1 ? rd_compl_done : bm_tag_valid == 1'b1 ? bm_done : 1'b0;
  assign OP_TAG = rd_compl_start == 1'b1 ? rd_compl_tag : bm_tag_valid == 1'b1 ? BM_TAG : 16'h0000;
endmodule

