module stratixiii_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg updateclk;
reg capture;
reg mainclk;
reg update;

reg [1:0] tmp;

always @(captnupdt or shiftnld or clk)
    begin
        case ({captnupdt, shiftnld})
            2'b10: {updateclk, capture, mainclk, update} = {clk, 1'b1, clk, 1'b1};
            2'b11: {updateclk, capture, mainclk, update} = {clk, 1'b1, clk, 1'b1};
            2'b01: {updateclk, capture, mainclk, update} = {clk, 1'b0, clk, 1'b0};
            default: {updateclk, capture, mainclk, update} = {clk, 1'b0, clk, 1'b0};
        endcase
    end

and (mainclk, mainclk, 1'b1);
and (updateclk, updateclk, 1'b1);
and (capture, capture, 1'b1);
and (update, update, 1'b1);

initial
    begin
        updateclk = 1'b0;
        capture = 1'b0;
        mainclk = 1'b0;
        update = 1'b0;
    end

endmodule

