            V_cnt <= 0;
            H_cnt <= 0;
        end
        else begin
            if (V_cnt == I_v_total - 1) begin
                V_cnt <= 0;
                H_cnt <= H_cnt + 1;
            end
            else begin
                V_cnt <= V_cnt + 1;
                H_cnt <= H_cnt;
            end
        end
    end
    always @(posedge I_pxl_clk or negedge I_rst_n) begin
        if (!I_rst_n) begin
            O_rden <= 0;
            O_de <= 0;
            O_hs <= 0;
            O_vs <= 0;
        end
        else begin
            O_rden <= Rden_w;
            O_de <= Pout_de_w;
            O_hs <= Pout_hs_w;
            O_vs <= Pout_vs_w;
        end
    end
    assign O_rden = Rden_w;
    assign O_de = Pout_de_w;
    assign O_hs = Pout_hs_w;
    assign O_vs = Pout_vs_w;
