module alu
    #(parameter WIDTH = 32)
    (   input  [WIDTH - 1 : 0] a,b,
        input  [2 : 0] m,
        output reg [WIDTH - 1 : 0] y,
        output reg zf,      
        output reg cf,      
        output reg of      
    );
always @(*)
    begin
        case (m)
            3'b000: y = a + b; cf = y[WIDTH - 1]; 
            3'b001: y = a - b; cf = y[WIDTH - 1]; 
            3'b010: y = a & b; 
            3'b011: y = a | b; 
            3'b100: y = a ^ b; 
            default: y = 0;
        endcase
        zf = (y == 0);
        of = (a[WIDTH - 1] ^ b[WIDTH - 1] ^ y[WIDTH - 1]) & cf;
    end
endmodule

module arriaii_first_stage_add_sub(
                                 dataa,
                                 datab,
                                 sign,
                                 operation,
                                 dataout
                                );


input [71  : 0 ] dataa;
input [71 : 0 ] datab;
input sign;
input [3:0] operation;


output [71: 0] dataout;
parameter dataa_width = 36;
parameter datab_width = 36;
parameter fsa_mode = "add";

reg [71:0] dataout_tmp;
reg [71:0] abs_b;
reg [71:0] abs_a;
reg sign_a;
reg sign_b;

wire [71:0] dataa_signed;
wire [71:0] datab_signed;

assign dataa_signed = (sign == 1'b1) ? (~dataa + 1'b1) : dataa;
assign datab_signed = (sign == 1'b1) ? (~datab + 1'b1) : datab;

always@(dataa_signed or datab_signed or operation)
begin
    case(operation)
        4'b0000: dataout_tmp = dataa_signed + datab_signed;
        4'b0001: dataout_tmp = dataa_signed - datab_signed;
        4'b0010: dataout_tmp = dataa_signed + datab_signed;
        4'b0011: dataout_tmp = dataa_signed - datab_signed;
        4'b0100: dataout_tmp = dataa_signed + datab_signed;
        4'b0101: dataout_tmp = dataa_signed - datab_signed;
        4'b0110: dataout_tmp = dataa_signed + datab_signed;
        4'b0111: dataout_tmp = dataa_signed - datab_signed;
        4'b1000: dataout_tmp = dataa_signed + datab_signed;
        4'b1001: dataout_tmp = dataa_signed - datab_signed;
        4'b1010: dataout_tmp = dataa_signed + datab_signed;
        4'b1011: dataout_tmp = dataa_signed - datab_signed;
        4'b1100: dataout_tmp = dataa_signed + datab_signed;
        4'b1101: dataout_tmp = dataa_signed - datab_signed;
        4'b1110: dataout_tmp = dataa_signed + datab_signed;
        4'b1111: dataout_tmp = dataa_signed - datab_signed;
        default: dataout_tmp = dataa_signed + datab_signed;
    endcase
end

assign dataout = dataout_tmp;

endmodule

