module pddm (
	input sdi, 
	input signed_data, 
	output [31:0] dout, 
	input ock, uck, 
	input rstn, clk
);
reg [31:0] sigma;
reg [31:0] delta;
reg [31:0] undersampled_sigma;
reg [31:0] deriv;
wire signed [31:0] dout;
always @(posedge clk or negedge rstn) begin
	if (!rstn) begin
		sigma <= 0;
		undersampled_sigma <= 0;
		delta <= 0;
		deriv <= 0;
	end else begin
		if (ock) begin
			sigma <= sigma + delta;
			if (sigma > 32'd18000000) begin
				sigma <= sigma - 32'd18000000;
			end
			if (sigma < 32'd-18000000) begin
				sigma <= sigma + 32'd18000000;
			end
		end
		if (uck) begin
			undersampled_sigma <= sigma;
		end
		if (sdi) begin
			delta <= 32'd1;
		end else begin
			delta <= 32'd-1;
		end
		if (signed_data) begin
			deriv <= sigma - undersampled_sigma;
		end else begin
			deriv <= sigma - undersampled_sigma;
		end
	end
end
assign dout = signed_data ? {deriv[31:0], 1'b0} : {deriv[31:0], 1'b1};
endmodule

module RegFile(
    output reg signed  [31:0] ReadData1, ReadData2,
    input [4:0] ReadReg1, ReadReg2, WriteReg,
    input signed [31:0] WriteData,
    input RegWrite, Clk
    );
reg signed [31:0] RegFile [31:0];
    always @(negedge Clk)
    begin
        if (ReadReg1 != 0)
            ReadData1 <= RegFile[ReadReg1];
        else
            ReadData1 <= 0;
        if (ReadReg2 != 0)
            ReadData2 <= RegFile[ReadReg2];
        else
            ReadData2 <= 0;
    end
    always @(posedge Clk)
    begin
        if (RegWrite)
            RegFile[WriteReg] <= WriteData;
    end
endmodule

