module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
reg[31:0] counter;
	reg[31:0] step;
	reg auto_clk;
	reg wasReady;

	assign Clk_CPU = (SW2) ? auto_clk : 1'b0;
	assign readn = keyReady;

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			counter <= 0;
			step <= 0;
			auto_clk <= 0;
			wasReady <= 0;
		end else begin
			if (keyReady) begin
				if (BTN_OK == 4'b0001) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else if (BTN_OK == 4'b0010) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 1;
					wasReady <= 1;
				end else if (BTN_OK == 4'b0100) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else if (BTN_OK == 4'b1000) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 1;
					wasReady <= 1;
				end else if (BTN_OK == 4'b0000) begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 1;
				end else begin
					counter <= 0;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 0;
				end
			end else if (wasReady) begin
				if (counter == 0) begin
					counter <= 1;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 0;
				end else begin
					counter <= counter - 1;
					step <= 0;
					auto_clk <= 0;
					wasReady <= 0;
				end
			end else if (counter == 0) begin
				counter <= 1;
				step <= 0;
				auto_clk <= 0;
				wasReady <= 0;
			end else begin
				counter <= counter - 1;
				step <= 0;
				auto_clk <= 0;
				wasReady <= 0;
			end
		end
	end

	always @(posedge clk or posedge rst) begin
		if (rst) begin
			clkdiv <= 0;
		end else begin
			if (counter == 0) begin
				clkdiv <= 0;
			end else begin
				clkdiv <= clkdiv + 1;
			end
		end
	end

endmodule

