    if (CLEAR_ON_INIT) begin
        for (i = 0; i < 2**ADDR_WIDTH; i = i + 1) begin
            mem[i] = 0;
        end
    end
end

always @(posedge clk) begin
    if (ENABLE_BYPASS && (raddr == waddr) && we) begin
        dout <= din;
    end else begin
        dout <= mem[raddr];
    end
end

always @(posedge clk) begin
    if (we) begin
        mem[waddr] <= din;
    end
end

endmodule

