module adapter_rgb_2_ppfifo #(
  parameter                 DATA_WIDTH = 24
)(
  input                             clk,
  input                             rst,

  input         [23:0]              i_rgb,
  input                             i_h_sync,
  input                             i_h_blank,
  input                             i_v_sync,
  input                             i_v_blank,
  input                             i_data_en,


  output                            o_ppfifo_clk,
  input       [1:0]                 i_ppfifo_rdy,
  output  reg [1:0]                 o_ppfifo_act,
  input       [23:0]                i_ppfifo_size,
  output  reg                       o_ppfifo_stb,
  output  reg [DATA_WIDTH - 1:0]    o_ppfifo_data


);
localparam  IDLE = 2'b00;
  localparam  READY = 2'b01;
  localparam  RELEASE = 2'b10;

  reg [1:0] r_state;
  reg [23:0] r_count;
  reg [23:0] r_ppfifo_size;

  assign o_ppfifo_clk = clk;
  assign o_ppfifo_act = {2{r_state == READY}};
  assign o_ppfifo_stb = r_state == READY;
  assign o_ppfifo_data = r_count[23:0];

  always @(posedge clk) begin
    if (rst) begin
      r_state <= IDLE;
      r_count <= 0;
      r_ppfifo_size <= 0;
    end else begin
      case (r_state)
        IDLE: begin
          if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
            r_state <= READY;
            r_ppfifo_size <= i_ppfifo_size;
          end
        end
        READY: begin
          if (i_ppfifo_rdy[0] && i_ppfifo_rdy[1]) begin
            r_state <= RELEASE;
          end
          if (i_data_en && !i_h_blank && !i_v_blank) begin
            r_count <= r_count + 1;
          end
        end
        RELEASE: begin
          if (r_count == r_ppfifo_size) begin
            r_state <= IDLE;
            r_count <= 0;
          end
        end
      endcase
    end
  end

endmodule

