module routing_buffer(clock, resetn, 
  i_datain, i_datain_valid, o_datain_stall, 
  o_dataout, i_dataout_stall, o_dataout_valid);

 input clock, resetn;
 input [DATA_WIDTH-1:0] i_datain;
 input i_datain_valid;
 output reg o_datain_stall;
 output reg [DATA_WIDTH-1:0] o_dataout;
 input i_dataout_stall;
 output reg o_dataout_valid;
parameter DATA_WIDTH = 32;
 parameter INSERT_REGISTER = 0;

 reg [DATA_WIDTH-1:0] data_in;
 reg data_in_valid;
 reg data_in_stall;
 reg data_out_valid;
 reg data_out_stall;

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    data_in <= 0;
    data_in_valid <= 0;
    data_in_stall <= 0;
    data_out_valid <= 0;
    data_out_stall <= 0;
  end
  else begin
    if (i_dataout_stall) begin
      data_in_stall <= 1;
    end
    else begin
      data_in_stall <= 0;
    end
    if (i_datain_valid && !data_in_stall) begin
      data_in <= i_datain;
      data_in_valid <= 1;
    end
    else begin
      data_in_valid <= 0;
    end
    if (data_in_valid && !data_in_stall) begin
      data_out_stall <= 1;
    end
    else begin
      data_out_stall <= 0;
    end
    if (data_in_valid && !data_in_stall && !data_out_stall) begin
      data_out_valid <= 1;
      o_dataout <= data_in;
    end
    else begin
      data_out_valid <= 0;
    end
  end
 end

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    o_datain_stall <= 0;
  end
  else begin
    o_datain_stall <= data_in_stall;
  end
 end

 always @(posedge clock or negedge resetn) begin
  if (!resetn) begin
    o_dataout_valid <= 0;
  end
  else begin
    o_dataout_valid <= data_out_valid;
  end
 end

endmodule

