  always @(posedge clk_100MHz, posedge reset) begin
    if((reset == 1'b1)) begin
      ticks <= 499999;
      clk_out <= 1'b0;
    end else begin
      ticks <= ticks + 1;
      if((ticks == 0)) begin
        clk_out <=  ~clk_out;
      end
    end
  end
  assign clk_100Hz = clk_out;
endmodule

