module Control(
		input clk,
		input start,
		output[3:0] direction,
		output ready
	);
reg[2:0] state;
	always @(posedge clk or posedge start) begin
		if(start) begin
			state <= 3'b000;
		end else begin
			if(state[1:0] == 2'b00) begin
				state <= 3'b001;
			end else begin
				if(state[2] == 1'b0) begin
					state <= state + 3'b001;
				end
			end
		end
	end
	assign direction = {state[2], state[2], state[1], state[0]};
	assign ready = (state[2:0] == 3'b000) ? 1'b1 : 1'b0;
endmodule

