    parameter S2 = 3'b001;
    parameter S3 = 3'b010;
    parameter S4 = 3'b011;
    parameter S5 = 3'b100;
    parameter S6 = 3'b101;
    reg [2:0] state, next;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S1;
        end else begin
            state <= next;
        end
    end
    always @(*) begin
        case (state)
            S1: if (x) next = S2; else next = S1;
            S2: if (x) next = S3; else next = S1;
            S3: if (x) next = S4; else next = S1;
            S4: if (x) next = S5; else next = S1;
            S5: if (x) next = S6; else next = S1;
            S6: if (x) next = S2; else next = S1;
            default: next = S1;
        endcase
    end
    assign z = (state == S6);
endmodule

