module SynFifo #
(
    parameter DATA_WIDTH = 8,
    parameter FIFO_DEPTH = 256
)
(clk,arstn,data_in,wrreq,rdreq,data_out,usedw,empty,full);

input clk;
input arstn;
input [DATA_WIDTH-1:0]data_in;
input wrreq;
input rdreq;
output [DATA_WIDTH-1:0]data_out;
output reg [clog2_FIFO_DEPTH:0]usedw;
output empty;
output full;
parameter clog2_FIFO_DEPTH = $clog2(FIFO_DEPTH);

reg [clog2_FIFO_DEPTH:0]wrptr;
reg [clog2_FIFO_DEPTH:0]rdptr;

reg [DATA_WIDTH-1:0]mem [0:FIFO_DEPTH-1];

assign data_out = mem[rdptr];

always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        wrptr <= 0;
    end else begin
        if(wrreq && !full) begin
            wrptr <= wrptr + 1;
        end
    end
end

always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        rdptr <= 0;
    end else begin
        if(rdreq && !empty) begin
            rdptr <= rdptr + 1;
        end
    end
end

always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        usedw <= 0;
    end else begin
        if(wrreq && !full) begin
            usedw <= usedw + 1;
        end
        if(rdreq && !empty) begin
            usedw <= usedw - 1;
        end
    end
end

assign empty = (wrptr == rdptr);
assign full = (wrptr == rdptr + 1) || (wrptr == 0 && rdptr == FIFO_DEPTH-1);

always @(posedge clk or negedge arstn) begin
    if(!arstn) begin
        mem[0] <= 0;
    end else begin
        if(wrreq && !full) begin
            mem[wrptr] <= data_in;
        end
    end
end

endmodule

