module testbench;
reg [2:0] A, B;
    wire A_greater, A_equal, A_less;
    integer i, error;

    comparator_3bit cmp(A_greater, A_equal, A_less, A, B);

    initial begin
        error = 0;
        for (i = 0; i < 100; i = i + 1) begin
            A = $random;
            B = $random;
            if (A_greater !== (A > B)) begin
                $display("Error at test case %d: A_greater = %b, A > B = %b", i, A_greater, A > B);
                error = error + 1;
            end
            if (A_equal !== (A == B)) begin
                $display("Error at test case %d: A_equal = %b, A == B = %b", i, A_equal, A == B);
                error = error + 1;
            end
            if (A_less !== (A < B)) begin
                $display("Error at test case %d: A_less = %b, A < B = %b", i, A_less, A < B);
                error = error + 1;
            end
        end
        if (error == 0) begin
            $display("=========== Your Design Passed ===========");
        end
        else begin
            $display("=========== Test completed with %d failures ===========", error);
        end
        $finish;
    end
endmodule

