module pn_gen_9 (
    input clk,
    input rst,
    input next,
    input [31:0] seed,
    output reg [31:0] num
  );
localparam SEED = 32'h00000001;


  reg [31:0] M_x, M_y, M_z, M_w;
  reg [31:0] M_w_d;
  wire [31:0] t;

  assign t = M_x[31] ^ M_x[30] ^ M_x[29] ^ M_x[28] ^ M_x[27] ^ M_x[26] ^ M_x[25] ^ M_x[24] ^ M_x[23] ^ M_x[22] ^ M_x[21] ^ M_x[20] ^ M_x[19] ^ M_x[18] ^ M_x[17] ^ M_x[16] ^ M_x[15] ^ M_x[14] ^ M_x[13] ^ M_x[12] ^ M_x[11] ^ M_x[10] ^ M_x[9] ^ M_x[8] ^ M_x[7] ^ M_x[6] ^ M_x[5] ^ M_x[4] ^ M_x[3] ^ M_x[2] ^ M_x[1] ^ M_x[0];

  always @(posedge clk) begin
    if (rst) begin
      M_x <= SEED;
      M_y <= SEED;
      M_z <= SEED;
      M_w <= SEED;
    end else begin
      M_x <= M_x_d;
      M_y <= M_y_d;
      M_z <= M_z_d;
      M_w <= M_w_d;
    end
  end

  always @(*) begin
    M_x_d = M_x;
    M_y_d = M_y;
    M_z_d = M_z;
    M_w_d = M_w;
    if (next) begin
      M_x_d = M_y;
      M_y_d = M_z;
      M_z_d = M_w;
      M_w_d = {M_w[30:0], t};
    end
  end

  assign num = M_w_q;
endmodule

