module clock_divider(
input wire clock,
output wire clock_div
); 

parameter [31:0] input_freq=100000000;
parameter [31:0] output_freq=1000000;
reg [31:0] counter = 0;
reg clock_signal = 1'b0;
  always @(posedge clock) begin
    if(counter < (input_freq / output_freq)) begin
      counter <= counter + 1;
    end
    else begin
      counter <= 0;
      clock_signal <=  ~clock_signal;
    end
  end
  assign clock_div = clock_signal;
endmodule

module cycloneiv_pciehip_pciexp_dcfiforam (data, wren, wraddress, rdaddress, wrclock, rdclock, q);
   input[data_width - 1:0] data; 
   input wren; 
   input[addr_width - 1:0] wraddress; 
   input[addr_width - 1:0] rdaddress; 
   input wrclock; 
   input rdclock; 
   output[data_width - 1:0] q;
parameter data_width = 32'd16; 
   parameter addr_width = 32'd10; 
   parameter addr_range = 32'd1024; 
   reg[addr_width - 1:0] rdaddress_d; 
   reg wren_d; 
   reg[addr_width - 1:0] wraddress_d; 
   reg[addr_width - 1:0] q_reg; 
   reg[data_width - 1:0] mem[addr_range - 1:0]; 
   assign q = q_reg; 
   always @(posedge wrclock) 
     begin 
        wren_d <= wren; 
        wraddress_d <= wraddress; 
     end 
   always @(posedge rdclock) 
     begin 
        rdaddress_d <= rdaddress; 
     end 
   always @(posedge wrclock) 
     begin 
        if (wren_d == 1'b1) 
          begin 
             mem[wraddress_d] <= data; 
          end 
     end 
   always @(posedge rdclock) 
     begin 
        if (wren_d == 1'b1) 
          begin 
             q_reg <= mem[rdaddress_d]; 
          end 
     end 
endmodule

