module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;

    reg  [lpm_width-1:0] result_tmp;

    integer i, j;

    initial
    begin
        if (lpm_width <= 0)
        begin
            $display("Value of lpm_width parameter must be greater than 0(ERROR)");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end

        if (lpm_size <= 0)
        begin
            $display("Value of lpm_size parameter must be greater than 0(ERROR)");
            $display("Time: %0t  Instance: %m", $time);
            $finish;
        end
    end

    always @ (data)
    begin
        for (i = 0; i < lpm_width; i = i + 1)
        begin
            result_tmp[i] = 1'b0;
            for (j = 0; j < lpm_size; j = j + 1)
            begin
                result_tmp[i] = result_tmp[i] | data[(j * lpm_width) + i];
            end
        end
    end

    assign result = result_tmp;

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg [NUM_DIV-1:0] cnt;
    reg clk_div;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if (cnt == (NUM_DIV/2 - 1)) begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

