module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
localparam IDLE = 0;
    localparam START_BIT = 1;
    localparam DATA_BITS = 2;
    localparam PARITY_BIT = 3;
    localparam STOP_BIT = 4;
    reg [2:0] state;
    reg [3:0] bit_counter;
    reg [7:0] shift_reg;
    reg parity;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
            bit_counter <= 0;
            shift_reg <= 0;
            parity <= 0;
            done <= 0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= START_BIT;
                        bit_counter <= 0;
                        shift_reg <= {1'b0, data_in, 1'b1};
                        parity <= ^data_in;
                        done <= 0;
                    end
                end
                START_BIT: begin
                    if (bit_counter == 0) begin
                        state <= DATA_BITS;
                        bit_counter <= bit_counter + 1;
                    end
                end
                DATA_BITS: begin
                    if (bit_counter < 8) begin
                        state <= DATA_BITS;
                        bit_counter <= bit_counter + 1;
                    end
                    else begin
                        state <= PARITY_BIT;
                        bit_counter <= bit_counter + 1;
                    end
                end
                PARITY_BIT: begin
                    if (bit_counter < 9) begin
                        state <= PARITY_BIT;
                        bit_counter <= bit_counter + 1;
                    end
                    else begin
                        state <= STOP_BIT;
                        bit_counter <= bit_counter + 1;
                    end
                end
                STOP_BIT: begin
                    if (bit_counter < 10) begin
                        state <= STOP_BIT;
                        bit_counter <= bit_counter + 1;
                    end
                    else begin
                        state <= IDLE;
                        done <= 1;
                    end
                end
                default: begin
                    state <= IDLE;
                    bit_counter <= 0;
                    shift_reg <= 0;
                    parity <= 0;
                    done <= 0;
                end
            endcase
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end
        else begin
            if (state == STOP_BIT) begin
                data_out <= shift_reg;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 0;
        end
        else begin
            if (state == DATA_BITS) begin
                shift_reg <= {shift_reg[6:0], 1'b0};
            end
            else if (state == PARITY_BIT) begin
                shift_reg <= {shift_reg[6:0], parity};
            end
        end
    end
endmodule

module muladd_3_stage_signed_8_bit(
	input signed [7:0] a,
	input signed [7:0] b,
	input signed [7:0] c,
	output [7:0] out,
	input clk);
logic signed [15:0] stage0;
	logic signed [15:0] stage1;
	logic signed [15:0] stage2;

	always @(posedge clk) begin
	stage0 <= (a * b) + c;
	stage1 <= stage0;
	stage2 <= stage1;
	end

	assign out = stage2;
endmodule

