module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(*) begin
        case (alu_ctrl)
            4'b0000: result = x + y;
            4'b0001: result = x - y;
            4'b0010: result = x * y;
            4'b0110: result = x / y;
            4'b0011: result = x & y;
            4'b0100: result = x | y;
            4'b0101: result = x ^ y;
            4'b0111: result = x < y ? 1 : 0;
            default: result = 0;
        endcase
    end
    always @(*) begin
        zero = (result == 0) ? 1 : 0;
    end
endmodule

module apb_master(


                  addr,
                  data_valid,
                  data,
                  data_dir,
             read_out_data,
             transaction_done,


                  apb_clk,
                  apb_reset,
                  apb_write,
                  apb_selx,
                  apb_en,
                  apb_wdata,
                  apb_rdata,
                  apb_ready,
                  apb_addr,
  				  apb_tranerr
                 );




  input     [7:0]       addr;
  input                 data_valid;  
  input     [31:0]      data;
  input                 data_dir;
  output [31:0]      read_out_data;
  output            transaction_done;


  input                 apb_clk;
  input                 apb_reset;
  output                apb_write;
  output                apb_selx;
  output                apb_en;
  output   [31:0]       apb_wdata;
  input    [31:0]       apb_rdata;
  input                 apb_ready;
  output   [7:0]        apb_addr;
  output   				apb_tranerr;
parameter IDLE = 2'b00;
parameter SETUP = 2'b01;
parameter ACCESS = 2'b10;
parameter ERROR = 2'b11;

reg [1:0] state;
reg [1:0] next_state;
reg [31:0] timeout_count;
reg [31:0] next_timeout_count;
reg [31:0] read_out_data;
reg transaction_done;
reg [31:0] apb_rdata;
reg apb_write;
reg apb_selx;
reg apb_en;
reg [31:0] apb_wdata;
reg apb_ready;
reg [7:0] apb_addr;
reg apb_tranerr;

always @(posedge apb_clk or posedge apb_reset) begin
  if (apb_reset) begin
    state <= IDLE;
    timeout_count <= 0;
    read_out_data <= 0;
    transaction_done <= 0;
    apb_rdata <= 0;
    apb_write <= 0;
    apb_selx <= 0;
    apb_en <= 0;
    apb_wdata <= 0;
    apb_ready <= 0;
    apb_addr <= 0;
    apb_tranerr <= 0;
  end
  else begin
    state <= next_state;
    timeout_count <= next_timeout_count;
    read_out_data <= read_out_data;
    transaction_done <= transaction_done;
    apb_rdata <= apb_rdata;
    apb_write <= apb_write;
    apb_selx <= apb_selx;
    apb_en <= apb_en;
    apb_wdata <= apb_wdata;
    apb_ready <= apb_ready;
    apb_addr <= apb_addr;
    apb_tranerr <= apb_tranerr;
  end
end

always @(*) begin
  next_state = IDLE;
  next_timeout_count = 0;
  read_out_data = 0;
  transaction_done = 0;
  apb_rdata = 0;
  apb_write = 0;
  apb_selx = 0;
  apb_en = 0;
  apb_wdata = 0;
  apb_ready = 0;
  apb_addr = 0;
  apb_tranerr = 0;
  case (state)
    IDLE: begin
      if (data_valid) begin
        next_state = SETUP;
        next_timeout_count = 0;
        apb_write = 0;
        apb_selx = 0;
        apb_en = 0;
        apb_wdata = 0;
        apb_ready = 0;
        apb_addr = 0;
        apb_tranerr = 0;
      end
    end
    SETUP: begin
      next_state = ACCESS;
      next_timeout_count = 0;
      apb_write = 0;
      apb_selx = 0;
      apb_en = 0;
      apb_wdata = 0;
      apb_ready = 0;
      apb_addr = 0;
      apb_tranerr = 0;
    end
    ACCESS: begin
      if (apb_ready) begin
        if (timeout_count == 0) begin
          next_state = IDLE;
          next_timeout_count = 0;
          read_out_data = apb_rdata;
          transaction_done = 1;
          apb_write = 0;
          apb_selx = 0;
          apb_en = 0;
          apb_wdata = 0;
          apb_ready = 0;
          apb_addr = 0;
          apb_tranerr = 0;
        end
        else begin
          next_state = ERROR;
          next_timeout_count = 0;
          read_out_data = 0;
          transaction_done = 0;
          apb_write = 0;
          apb_selx = 0;
          apb_en = 0;
          apb_wdata = 0;
          apb_ready = 0;
          apb_addr = 0;
          apb_tranerr = 0;
        end
      end
      else begin
        next_state = ACCESS;
        next_timeout_count = timeout_count + 1;
        apb_write = 0;
        apb_selx = 0;
        apb_en = 0;
        apb_wdata = 0;
        apb_ready = 0;
        apb_addr = 0;
        apb_tranerr = 0;
      end
    end
    ERROR: begin
      next_state = IDLE;
      next_timeout_count = 0;
      read_out_data = 0;
      transaction_done = 0;
      apb_write = 0;
      apb_selx = 0;
      apb_en = 0;
      apb_wdata = 0;
      apb_ready = 0;
      apb_addr = 0;
      apb_tranerr = 0;
    end
    default: begin
      next_state = IDLE;
      next_timeout_count = 0;
      read_out_data = 0;
      transaction_done = 0;
      apb_write = 0;
      apb_selx = 0;
      apb_en = 0;
      apb_wdata = 0;
      apb_ready = 0;
      apb_addr = 0;
      apb_tranerr = 0;
    end
  endcase
end

always @(*) begin
  apb_rdata = 0;
  apb_write = 0;
  apb_selx = 0;
  apb_en = 0;
  apb_wdata = 0;
  apb_ready = 0;
  apb_addr = 0;
  apb_tranerr = 0;
  case (state)
    IDLE: begin
      apb_rdata = 0;
      apb_write = 0;
      apb_selx = 0;
      apb_en = 0;
      apb_wdata = 0;
      apb_ready = 0;
      apb_addr = 0;
      apb_tranerr = 0;
