module PulseCounter(
input wire clk,
output wire pulse
); 

parameter [31:0] upper_bound=28;
reg [27:0] count = 1'b0;
  always @(posedge clk) begin
    if(count == (upper_bound - 1)) begin
      count <= {28{1'b0}};
    end
    else begin
      count <= count + 1;
    end
  end
  assign pulse = count == (upper_bound - 1) ? 1'b1 : 1'b0;
endmodule

