module uart_tx_tester ( input clk_50M, input run_test_raw, input tx_busy, output reg [7:0] data_out, output reg trigger );
parameter [1:0]
  STATE_IDLE = 0,
  STATE_LOAD_DATA = 1,
  STATE_TRIGGER_TX = 2,
  STATE_WAIT_TX_DONE = 3,
  STATE_PAUSE = 4;

reg [1:0] state;
reg [3:0] data_pos;
reg [3:0] delay;

always @(posedge clk_50M) begin
  if (run_test_raw) begin
    case (state)
      STATE_IDLE: begin
        if (tx_busy) begin
          state <= STATE_LOAD_DATA;
          data_pos <= 0;
          delay <= 0;
        end
      end
      STATE_LOAD_DATA: begin
        if (delay == 0) begin
          data_out <= "Hello World! ";
          state <= STATE_TRIGGER_TX;
        end
        else begin
          delay <= delay - 1;
        end
      end
      STATE_TRIGGER_TX: begin
        if (tx_busy) begin
          state <= STATE_WAIT_TX_DONE;
        end
      end
      STATE_WAIT_TX_DONE: begin
        if (!tx_busy) begin
          state <= STATE_PAUSE;
        end
      end
      STATE_PAUSE: begin
        if (delay == 0) begin
          state <= STATE_LOAD_DATA;
          data_pos <= data_pos + 1;
          delay <= MSG_DELAY;
        end
        else begin
          delay <= delay - 1;
        end
      end
      default: begin
        state <= STATE_IDLE;
      end
    endcase
  end
end

parameter MSG_DELAY = 100000000;

endmodule

