module KEY_MUX
(
	input PS2_CLK,
	input PS2_DAT,
	output [9:0]LEDR,
	output [6:0]HEX0,
	output [6:0]HEX1
);
reg [3:0]S, NS;
	reg [7:0]in1, in2, in3, out;
	assign LEDR[3:0] = S;
	assign LEDR[9:8] = NS;
	assign HEX0 = in1;
	assign HEX1 = in2;
	assign out = in3;
	assign scan_code = out;
	always @(posedge PS2_CLK)
	begin
		NS = S;
		case (S)
			0: begin
				NS = 1;
				in1 = 0;
				in2 = 0;
				in3 = 0;
			end
			1: begin
				NS = 2;
				in1 = 0;
				in2 = 0;
				in3 = 0;
			end
			2: begin
				NS = 3;
				in1 = 0;
				in2 = 0;
				in3 = 0;
			end
			3: begin
				NS = 0;
				in1 = 0;
				in2 = 0;
				in3 = 0;
			end
			default: NS = 0;
		endcase
		if (scan_code != 0)
		begin
			case (S)
				0: begin
					in1 = scan_code;
					in2 = 0;
					in3 = 0;
				end
				1: begin
					in1 = scan_code;
					in2 = 0;
					in3 = 0;
				end
				2: begin
					in1 = scan_code;
					in2 = 0;
					in3 = 0;
				end
				3: begin
					in1 = scan_code;
					in2 = 0;
					in3 = 0;
				end
				default: begin
					in1 = scan_code;
					in2 = 0;
					in3 = 0;
				end
			endcase
		end
	end
endmodule

