module hardcopyiv_ram_register (
                             d,
                             clk,
                             aclr,
                             devclrn,
                             devpor,
                             stall,
                             ena,
                             q,
                             aclrout
                            );  

input [width - 1:0] d;    
input clk;                
input aclr;               
input devclrn,devpor;     
input stall; 
input ena;                
output [width - 1:0] q;   
output aclrout;
parameter width = 1;      
parameter lpm_type = "hardcopyiv_ram_register";  

reg [width - 1:0] q_tmp;  
wire [width - 1:0] q_wire;  

specify
    (posedge clk => (q +: q_tmp)) = (0, 0);
    (posedge aclr => (q +: q_tmp)) = (0, 0);
    (posedge devclrn => (q +: q_tmp)) = (0, 0);
    (posedge devpor => (q +: q_tmp)) = (0, 0);
endspecify

buf (q_wire, q_tmp);
and (q, q_wire, ena);

always @(posedge clk or posedge aclr or posedge devclrn or posedge devpor)
    begin
        if (devclrn === 1'b0 || devpor === 1'b0)
            q_tmp <= {((width - 1)-(0)+1){1'b0}};
        else if (aclr === 1'b1)
            q_tmp <= {((width - 1)-(0)+1){1'b0}};
        else if (stall === 1'b0)
            q_tmp <= d;
    end

and (aclrout, aclr, ena);

endmodule

