module file_writer(input_a,input_a_stb,clk,rst,input_a_ack);

  input     clk;
  input     rst;

  input     [63:0] input_a;
  input     input_a_stb;
  output    input_a_ack;
reg [1:0] state;
  reg [63:0] value;
  reg s_input_a_ack;
  wire [63:0] input_a;
  wire input_a_stb;
  wire input_a_ack;

  assign input_a_ack = s_input_a_ack;
  assign input_a = value;
  assign input_a_stb = input_a_stb;

  always @(posedge clk or posedge rst) begin
    if (rst) begin
      state <= 0;
      s_input_a_ack <= 0;
    end
    else begin
      case (state)
        0: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 1;
            s_input_a_ack <= 0;
          end
        end
        1: begin
          if (input_a_stb) begin
            $fdisplaya("resp_z",value);
            $fdisplaya("resp_z",value[31:0]);
            $fdisplaya("resp_z",value[63:32]);
            state <= 0;
            s_input_a_ack <= 1;
          end
        end
      endcase
    end
  end

endmodule

