module bridge_1x2(                                 
    input                           clk,          
    input                           resetn,       
    input                           cpu_data_en,      
    input  [3                   :0] cpu_data_wen,     
    input  [31                  :0] cpu_data_addr,    
    input  [31                  :0] cpu_data_wdata,   
    output [31                  :0] cpu_data_rdata,   
    output                          data_sram_en,     
    output [3                   :0] data_sram_wen,    
    output [31                  :0] data_sram_addr,   
    output [31                  :0] data_sram_wdata,  
    input  [31                  :0] data_sram_rdata,  
    output                          conf_en,          
    output [3                   :0] conf_wen,         
    output [31                  :0] conf_addr,        
    output [31                  :0] conf_wdata,       
    input  [31                  :0] conf_rdata        
);
parameter CONF_ADDR_BASE = 32'h00000000;
parameter CONF_ADDR_MASK = 32'h00000000;

reg sel_sram;
reg sel_conf;

assign data_sram_en = cpu_data_en;
assign conf_en = cpu_data_en;

assign data_sram_wen = cpu_data_wen & sel_sram;
assign conf_wen = cpu_data_wen & sel_conf;

assign data_sram_addr = cpu_data_addr & sel_sram;
assign conf_addr = cpu_data_addr & sel_conf;

assign data_sram_wdata = cpu_data_wdata;
assign conf_wdata = cpu_data_wdata;

assign cpu_data_rdata = {data_sram_rdata, conf_rdata};

always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
        sel_sram <= 1'b0;
        sel_conf <= 1'b0;
    end else begin
        sel_sram <= (cpu_data_addr >= CONF_ADDR_BASE) ? 1'b0 : 1'b1;
        sel_conf <= (cpu_data_addr >= CONF_ADDR_BASE) ? 1'b1 : 1'b0;
    end
end

endmodule

