module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg f1, f2;
    wire q_add, q_reset;
    assign q_add = ~q_reg[maxbit-1];
    assign q_reset = q_reg[maxbit-1];
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
        end else begin
            q_reg <= q_next;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            case (q_reg)
                0: begin
                    if (f1 == f2) begin
                        out <= f1;
                    end
                end
                maxbit-1: begin
                    out <= 1;
                end
                default: begin
                    out <= 0;
                end
            endcase
        end
    end
endmodule

