      x_next <= 32'b00000000000000000000000000000001;
      sqrt <= 32'b00000000000000000000000000000001;
      out_sqrt_reg <= 32'b00000000000000000000000000000001;
      val_comb <= 1'b0;
      z_comb <= 1'b0;
      val_ff <= 1'b0;
      z_ff <= 1'b0;
    end else begin
      x_i_mux <= x_i;
