module barrel_shifter_tb;
reg [7:0] in;
	reg [3:0] shift;
	reg [3:0] control;
	wire [7:0] out;
	reg [7:0] expected;
	integer error = 0;

	barrel_shifter uut (
		.in(in), 
		.shift(shift), 
		.control(control), 
		.out(out)
	);

	initial begin
		shift = 4;
		control = 0;
		in = 128;
		expected = 32;
		#10;
		if (out !== expected) begin
			$display("Failed shift by %d positions", shift);
			error = 1;
		end
		#10;
		shift = 2;
		control = 0;
		in = 128;
		expected = 16;
		#10;
		if (out !== expected) begin
			$display("Failed shift by %d positions", shift);
			error = 1;
		end
		#10;
		shift = 1;
		control = 0;
		in = 128;
		expected = 8;
		#10;
		if (out !== expected) begin
			$display("Failed shift by %d positions", shift);
			error = 1;
		end
		#10;
		shift = 7;
		control = 0;
		in = 255;
		expected = 1;
		#10;
		if (out !== expected) begin
			$display("Failed shift by %d positions", shift);
			error = 1;
		end
		#10;
		if (error == 0) begin
			$display("PASSED");
		end
		$finish;
	end
endmodule

