module SCK_control_slave( input wire SCK_in, input wire CPOL, input wire CPHA, input wire idle, output reg S_BaudRate, output wire Shift_clk, output wire Sample_clk );
reg Shift_clk_int, Sample_clk_int;
assign Shift_clk = Shift_clk_int;
assign Sample_clk = Sample_clk_int;
always @ (Shift_clk_int or Sample_clk_int or S_BaudRate or idle or SCK_in or CPOL or CPHA)
begin
	if (Shift_clk_int == 1'b1)
		Shift_clk_int = 1'b0;
	else if (Sample_clk_int == 1'b1)
		Shift_clk_int = 1'b1;
	else if (idle == 1'b0 && S_BaudRate == 1'b1)
		Shift_clk_int = 1'b1;
	else if (idle == 1'b0 && S_BaudRate == 1'b0)
		Shift_clk_int = 1'b0;
end
always @ (Shift_clk_int or Sample_clk_int or S_BaudRate or idle or SCK_in or CPOL or CPHA)
begin
	if (Sample_clk_int == 1'b1)
		Sample_clk_int = 1'b0;
	else if (Shift_clk_int == 1'b1 && idle == 1'b0 && S_BaudRate == 1'b0)
		Sample_clk_int = 1'b1;
	else if (Shift_clk_int == 1'b0 && idle == 1'b0 && S_BaudRate == 1'b0)
		Sample_clk_int = 1'b0;
end
always @ (Shift_clk_int or Sample_clk_int or S_BaudRate or idle or SCK_in or CPOL or CPHA)
begin
	case ({CPOL, CPHA})
		2'b00: S_BaudRate = 1'b0;
		2'b01: S_BaudRate = 1'b1;
		2'b10: S_BaudRate = 1'b1;
		2'b11: S_BaudRate = 1'b0;
	endcase
end
endmodule

