module UART_rx(
input wire clk,
input wire reset,
input wire rx_data_in,
output reg [7:0] rx_data_out
); 

parameter [31:0] BAUD_RATE=115200;
parameter [31:0] BAUD_COUNTER_WIDTH=10;
parameter [1:0]
  IDLE = 0,
  START = 1,
  DATA = 2,
  STOP = 3;
reg [1:0] state = IDLE;
reg [BAUD_COUNTER_WIDTH - 1:0] baud_counter = 0;
reg [7:0] rx_data = 0;
  always @(posedge clk, posedge reset) begin
    if((reset == 1'b1)) begin
      state <= IDLE;
      baud_counter <= 0;
      rx_data <= 0;
    end else begin
      case(state)
      IDLE : begin
        if((rx_data_in == 1'b0)) begin
          state <= START;
          baud_counter <= 0;
        end
      end
      START : begin
        if((baud_counter == (BAUD_RATE / 2))) begin
          state <= DATA;
          baud_counter <= 0;
        end
        else begin
          baud_counter <= baud_counter + 1;
        end
      end
      DATA : begin
        if((baud_counter == (BAUD_RATE / 2))) begin
          rx_data <= {rx_data[6:0],rx_data_in};
          baud_counter <= 0;
        end
        else begin
          baud_counter <= baud_counter + 1;
        end
      end
      STOP : begin
        if((baud_counter == (BAUD_RATE / 2))) begin
          state <= IDLE;
          rx_data_out <= rx_data;
          baud_counter <= 0;
        end
        else begin
          baud_counter <= baud_counter + 1;
        end
      end
      endcase
    end
  end
endmodule

module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30; 
parameter count = 4; 
reg [2:0]delay; 
reg [n-1:0]s_in; 
top t1(clk, reset, rxD, s_in, signal, counter); 
always @(posedge clk or posedge reset) begin 
    if (reset) begin 
        counter <= 0; 
        delay <= 0; 
    end 
    else begin 
        if (counter == count) begin 
            delay <= delay + 1; 
            if (delay == 0) begin 
                signal <= 1; 
                counter <= 0; 
            end 
        end 
        else begin 
            sout <= {s_in, sout[n-1:1]}; 
            counter <= counter + 1; 
        end 
    end 
end 
endmodule

