module bufferDatapointMemoryAccess(
  input         clock,
  input         reset,
  input         io_wrEna,
  input  [9:0]  io_Addr,
  input  [15:0] io_dataIn,
  output [15:0] io_rdData
);
reg [15:0] ram[1023:0];
  wire [15:0] rdData;
  wire [15:0] wrData;
  wire [9:0]  wrAddr;
  wire        wrEna;
  wire        rdEna;
  assign rdData = ram[io_Addr];
  assign wrAddr = io_Addr;
  assign wrData = io_dataIn;
  assign wrEna = io_wrEna;
  assign rdEna = ~io_wrEna;
  assign io_rdData = rdData;
  always @(posedge clock) begin
    if (reset) begin
      ram[0] <= 0;
    end else if (wrEna) begin
      ram[wrAddr] <= wrData;
