module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] H_ACTIVE=640;
parameter [31:0] H_FRONT=16;
parameter [31:0] H_BACK=48;
parameter [31:0] H_RETRACE=96;
parameter [31:0] V_ACTIVE=480;
parameter [31:0] V_FRONT=10;
parameter [31:0] V_BACK=33;
parameter [31:0] V_RETRACE=2;
reg [9:0] h_count_reg = 1'b0;
reg [9:0] v_count_reg = 1'b0;
  always @(posedge clk, posedge rst) begin
    if((rst == 1'b1)) begin
      h_count_reg <= {10{1'b0}};
      v_count_reg <= {10{1'b0}};
    end else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
    end
  end
  always @(h_count_reg, v_count_reg) begin
    if((h_count_reg < H_ACTIVE)) begin
      hsync <= 1'b1;
    end
    else begin
      hsync <= 1'b0;
    end
    if((v_count_reg < V_ACTIVE)) begin
      vsync <= 1'b1;
    end
    else begin
      vsync <= 1'b0;
    end
    if((h_count_reg < H_ACTIVE)) begin
      active <= 1'b1;
    end
    else begin
      active <= 1'b0;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
endmodule

