    reg stop;
    reg [7:0] i;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            start <= 0;
            stop <= 0;
            data <= 0;
            done <= 0;
        end
        else begin
            if (start) begin
                if (stop) begin
                    done <= 1;
                    start <= 0;
