                        end
                    end
                    else begin
                        data[i] <= in;
                        i <= i + 1;
                    end
                end
            end
            else begin
                if (in == 0) begin
                    start <= 1;
                    stop <= 0;
                end
                else begin
                    start <= 0;
                    stop <= 0;
                end
            end
        end
    end
