module TopModule(
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    input dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
    );
reg falling;
    reg [1:0] state;
    reg [1:0] next_state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            falling <= 1'b0;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
        end
        else begin
            state <= next_state;
            falling <= 1'b0;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            case (state)
                2'b00: begin
                    if (bump_left) begin
                        next_state <= 2'b01;
                        walk_right <= 1'b1;
                        walk_left <= 1'b0;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                        walk_right <= 1'b0;
                        walk_left <= 1'b1;
                    end
                    else if (ground) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                    else begin
                        next_state <= 2'b00;
                        falling <= 1'b1;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                end
                2'b01: begin
                    if (bump_left) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b1;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                        walk_right <= 1'b1;
                        walk_left <= 1'b0;
                    end
                    else if (ground) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                    else begin
                        next_state <= 2'b00;
                        falling <= 1'b1;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                end
                2'b10: begin
                    if (bump_left) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b1;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                        walk_right <= 1'b1;
                        walk_left <= 1'b0;
                    end
                    else if (ground) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                    else begin
                        next_state <= 2'b00;
                        falling <= 1'b1;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                end
                2'b11: begin
                    if (bump_left) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b1;
                    end
                    else if (bump_right) begin
                        next_state <= 2'b10;
                        walk_right <= 1'b1;
                        walk_left <= 1'b0;
                    end
                    else if (ground) begin
                        next_state <= 2'b00;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                    else begin
                        next_state <= 2'b00;
                        falling <= 1'b1;
                        walk_right <= 1'b0;
                        walk_left <= 1'b0;
                    end
                end
                default: begin
                    next_state <= 2'b00;
                    falling <= 1'b0;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
            endcase
            if (dig) begin
                if (ground) begin
                    next_state <= 2'b00;
                    falling <= 1'b0;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
                else if (falling) begin
                    next_state <= 2'b00;
                    falling <= 1'b0;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
                else begin
                    next_state <= 2'b00;
                    falling <= 1'b0;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            end
            else if (falling) begin
                next_state <= 2'b00;
                falling <= 1'b0;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
                aaah <= 1'b0;
                digging <= 1'b0;
            end
            else if (ground) begin
                next_state <= 2'b00;
                falling <= 1'b0;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
                aaah <= 1'b0;
                digging <= 1'b0;
            end
            else begin
                next_state <= 2'b00;
                falling <= 1'b0;
                walk_left <= 1'b1;
                walk_right <= 1'b0;
                aaah <= 1'b0;
                digging <= 1'b0;
            end
        end
    end
    always @(posedge clk) begin
        if (areset) begin
            aaah <= 1'b0;
        end
        else begin
            if (falling) begin
                aaah <= 1'b1;
            end
            else begin
                aaah <= 1'b0;
            end
        end
    end
    always @(posedge clk) begin
        if (areset) begin
            falling <= 1'b0;
        end
        else begin
            if (falling) begin
                falling <= 1'b0;
            end
            else begin
                if (ground) begin
                    falling <= 1'b0;
                end
                else begin
                    falling <= 1'b1;
                end
            end
        end
    end
    always @(posedge clk) begin
        if (areset) begin
            walk_left <= 1'b1;
            walk_right <= 1'b0;
        end
        else begin
            if (falling) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end
            else begin
                if (dig) begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
                else begin
                    if (bump_left) begin
                        walk_left <= 1'b0;
                        walk_right <= 1'b1;
                    end
                    else if (bump_right) begin
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end
                    else begin
                        walk_left <= 1'b1;
                        walk_right <= 1'b0;
                    end
                end
            end
        end
    end
    always @(posedge clk) begin
        if (areset) begin
            digging <= 1'b0;
        end
        else begin
            if (dig) begin
                digging <= 1'b1;
            end
            else begin
                digging <= 1'b0;
            end
        end
    end
endmodule

