module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);
reg [1:0] state;
  reg [1:0] next_state;
  assign walk_left = state[0];
  assign walk_right = state[1];
  always @(posedge clk) begin
    if (areset) begin
      state <= 2'b00;
    end else begin
      state <= next_state;
    end
  end
  always @(state, bump_left, bump_right) begin
    case (state)
      2'b00: begin
        if (bump_left) begin
          next_state = 2'b01;
        end else if (bump_right) begin
          next_state = 2'b10;
        end else begin
          next_state = 2'b00;
        end
      end
      2'b01: begin
        if (bump_left) begin
          next_state = 2'b00;
        end else if (bump_right) begin
          next_state = 2'b11;
        end else begin
          next_state = 2'b01;
        end
      end
      2'b10: begin
        if (bump_left) begin
          next_state = 2'b00;
        end else if (bump_right) begin
          next_state = 2'b11;
        end else begin
          next_state = 2'b10;
        end
      end
      2'b11: begin
        if (bump_left) begin
          next_state = 2'b00;
        end else if (bump_right) begin
          next_state = 2'b10;
        end else begin
          next_state = 2'b11;
        end
      end
      default: begin
        next_state = 2'b00;
      end
    endcase
  end
endmodule

