      end else begin
        if (state == 0) begin
          state <= 1;
          done_reg <= 0;
        end else if (state == 1) begin
          state <= 2;
          done_reg <= 0;
        end else if (state == 2) begin
          state <= 0;
          done_reg <= 1;
        end
      end
    end
  end
  assign done = done_reg;
endmodule

