        end else begin
          next_state = S0;
        end
      end
      S7: begin
        if (x == 1'b0) begin
          next_state = S4;
        end else begin
          next_state = S0;
        end
      end
      default: begin
        next_state = S0;
      end
    endcase
  end
  always @(posedge clk) begin
    if (!aresetn) begin
      z <= 1'b0;
    end else begin
      case (state)
        S0: begin
          z <= 1'b0;
        end
        S1: begin
          z <= 1'b0;
