  reg done_reg;
  assign done = done_reg;
  always @(posedge clk) begin
    if (reset) begin
      state <= 0;
      start <= 0;
      stop <= 0;
      idle <= 1;
      done_reg <= 0;
    end
    else begin
      if (idle) begin
        if (in == 0) begin
          start <= 1;
