        end
        else begin
          if (state == 0) begin
            if (in == 0) begin
              state <= state + 1;
            end
          end
          else if (state == 8) begin
            if (in == 1) begin
              state <= 0;
              done_reg <= 1;
            end
          end
          else begin
            if (in == 1) begin
              state <= state + 1;
