module TopModule (
  input clk,
  input load,
  input [255:0] data,
  output reg [255:0] q
);
always @(posedge clk) begin
    if (load) begin
      q <= data;
    end else begin
      for (int i = 0; i < 256; i = i + 1) begin
        int x = i % 16;
        int y = i / 16;
        int neighbours = 0;
        neighbours += (q[(y+1)%16 + (x+1)%16] ? 1 : 0;
        neighbours += (q[(y+1)%16 + (x)%16] ? 1 : 0;
        neighbours += (q[(y+1)%16 + (x-1)%16] ? 1 : 0;
        neighbours += (q[(y)%16 + (x+1)%16] ? 1 : 0;
        neighbours += (q[(y)%16 + (x-1)%16] ? 1 : 0;
        neighbours += (q[(y-1)%16 + (x+1)%16] ? 1 : 0;
        neighbours += (q[(y-1)%16 + (x)%16] ? 1 : 0;
        neighbours += (q[(y-1)%16 + (x-1)%16] ? 1 : 0;
        if (neighbours == 0) begin
          q[i] <= 0;
        end else if (neighbours == 1) begin
          q[i] <= 0;
        end else if (neighbours == 2) begin
          q[i] <= q[i];
        end else if (neighbours == 3) begin
          q[i] <= 1;
        end else if (neighbours == 4) begin
          q[i] <= 0;
        end
      end
    end
  end
endmodule

